 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Split at all-zero separator lines; each panel's marked cells are non-background.
    def spans(n, sep):
        out=[]; s=0
        for i in range(n):
            if sep(i):
                if s<i: out.append((s,i))
                s=i+1
        if s<n: out.append((s,n))
        return out
    rs=spans(h,lambda r: len(set(grid[r]))==1 and grid[r][0]==0)
    cs=spans(w,lambda c: all(grid[r][c]==0 for r in range(h)))
    # Background is the common non-separator color. Mark the panel whose two anomalies
    # are in one column with a two-row gap (the repeated pair motif in the demos).
    vals=[v for row in grid for v in row if v!=0]
    bg=max(set(vals),key=vals.count)
    out=[]
    for a,b in rs:
        row=[]
        for x,y in cs:
            pts=[(r-a,c-x) for r in range(a,b) for c in range(x,y) if grid[r][c] not in (0,bg)]
            mark=(len(pts)==2 and pts[0][1]==pts[1][1] and abs(pts[0][0]-pts[1][0])==2)
            row.append(1 if mark else bg)
        out.append(row)
    return out
